const cmds=[
"prusa-slicer --info /app/output/model.stl",
"prusa-slicer --export-gcode --load /opt/slicer/p1s_pla_0.20mm_nosupport.ini --output /tmp/dino-validation.gcode /app/output/model.stl",
"python3 - <<'PY'
import trimesh, numpy as np
from shapely.ops import unary_union, transform
files=['/app/output/parts/parts_1.stl','/app/output/parts/parts_2.stl','/app/output/parts/parts_3.stl','/app/output/parts/parts_4.stl']
meshes=[trimesh.load(p,force='mesh') for p in files]
zvals=[.1,.5,.9,1.3,1.7,2.1,2.5,2.9,3.3,3.7,4.1,4.5,5.1,5.7]
def section(mesh,z):
 s=mesh.section(plane_origin=[0,0,z],plane_normal=[0,0,1])
 if s is None:return None
 p,T=s.to_2D(); poly=p.polygons_full
 conv=lambda x,y,z=None:(T[0,0]*x+T[0,1]*y+T[0,3],T[1,0]*x+T[1,1]*y+T[1,3])
 return unary_union([transform(conv,q) for q in poly]) if poly else None
def moved(m,angle,cx):
 a=np.deg2rad(angle);c=np.cos(a);s=np.sin(a);q=m.copy()
 q.apply_transform(np.array([[c,-s,0,cx*(1-c)],[s,c,0,-cx*s],[0,0,1,0],[0,0,0,1]]));return q
for j,(f,m,cx) in enumerate([(meshes[0],meshes[1],14.8),(meshes[1],meshes[2],31.0),(meshes[2],meshes[3],44.0)],1):
 worst=0
 for angle in range(-20,21,2):
  q=moved(m,angle,cx)
  for z in zvals:
   a=section(f,z);b=section(q,z)
   if a is not None and b is not None:worst=max(worst,a.intersection(b).area)
 print('joint',j,'max section overlap mm2',round(worst,8),'samples',21*len(zvals))
PY"
];
