import trimesh, numpy as np
from shapely.ops import unary_union, transform
files=['/app/output/parts/parts_1.stl','/app/output/parts/parts_2.stl','/app/output/parts/parts_3.stl','/app/output/parts/parts_4.stl']
ms=[trimesh.load(p,force='mesh') for p in files]
zv=[.1,.5,.9,1.3,1.7,2.1,2.5,2.9,3.3,3.7,4.1,4.5,5.1,5.7]
def poly(m,z):
 s=m.section(plane_origin=[0,0,z],plane_normal=[0,0,1])
 if s is None:return None
 p,T=s.to_2D();conv=lambda x,y,z=None:(T[0,0]*x+T[0,1]*y+T[0,3],T[1,0]*x+T[1,1]*y+T[1,3])
 ps=p.polygons_full
 return unary_union([transform(conv,q) for q in ps]) if ps else None
def rot(m,a,cx):
 q=m.copy();a=np.deg2rad(a);c=np.cos(a);s=np.sin(a)
 q.apply_transform(np.array([[c,-s,0,cx*(1-c)],[s,c,0,-cx*s],[0,0,1,0],[0,0,0,1]]));return q
